/**
 * Patch flags are optimization hints generated by the compiler.
 *
 * When a block with `dynamicChildren` is encountered during diff, the algorithm
 * enters "optimized mode". In this mode, we know that the VDOM is produced by
 * a render function generated by the compiler, so the algorithm only needs to
 * handle updates explicitly marked by these patch flags.
 *
 * Patch flags can be combined using bitwise OR (`|`) and checked using bitwise
 * AND (`&`), e.g.
 *
 * ```rust
 * # use verter_core::utils::vue::patch_flags::PatchFlags;
 * let flag = PatchFlags::Text
 *     .into_flag()
 *     .add(PatchFlags::Class);
 *
 * if flag.contains(PatchFlags::Text) {
 *     // ...
 * }
 * ```
 *
 * See the renderer diffing logic for how these flags are used at runtime.
 */

#[repr(i16)]
#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
pub enum PatchFlags {
    /**
     * Indicates an element with dynamic textContent
     * (children fast path)
     */
    Text = 1,

    /**
     * Indicates an element with dynamic class binding.
     */
    Class = 1 << 1,

    /**
     * Indicates an element with dynamic style.
     *
     * The compiler pre-compiles static string styles into static objects
     * and hoists inline static objects.
     *
     * Example:
     * ```js
     * style="color: red"
     * :style="{ color: 'red' }"
     * ```
     *
     * both become:
     *
     * ```js
     * const style = { color: 'red' }
     * render() { return h('div', { style }) }
     * ```
     */
    Style = 1 << 2,

    /**
     * Indicates an element that has non-class/style dynamic props.
     *
     * Can also be present on components with any dynamic props (including
     * class/style).
     *
     * When this flag is present, the vnode also has a `dynamicProps` array
     * containing the keys of props that may change, allowing the runtime
     * to diff them faster without worrying about removed props.
     */
    Props = 1 << 3,

    /**
     * Indicates an element with props with dynamic keys.
     *
     * When keys change, a full diff is always needed to remove the old key.
     * This flag is mutually exclusive with CLASS, STYLE, and PROPS.
     */
    FullProps = 1 << 4,

    /**
     * Indicates an element that requires props hydration
     * (but not necessarily patching).
     *
     * Examples:
     * - event listeners
     * - v-bind with `.prop` modifier
     */
    NeedHydration = 1 << 5,

    /**
     * Indicates a fragment whose children order does not change.
     */
    StableFragment = 1 << 6,

    /**
     * Indicates a fragment with keyed or partially keyed children.
     */
    KeyedFragment = 1 << 7,

    /**
     * Indicates a fragment with unkeyed children.
     */
    UnkeyedFragment = 1 << 8,

    /**
     * Indicates an element that only needs non-props patching,
     * such as refs or directives (onVnodeXXX hooks).
     *
     * Since every patched vnode checks for refs and onVnodeXXX hooks,
     * this flag simply marks the vnode so that the parent block will track it.
     */
    NeedPatch = 1 << 9,

    /**
     * Indicates a component with dynamic slots.
     *
     * Examples:
     * - slots referencing a `v-for` iterated value
     * - dynamic slot names
     *
     * Components with this flag are always force-updated.
     */
    DynamicSlots = 1 << 10,

    /**
     * Indicates a fragment that was created only because the user placed
     * comments at the root level of a template.
     *
     * This is a dev-only flag since comments are stripped in production.
     */
    DevRootFragment = 1 << 11,

    /**
     * -------------------------------------------------------------------------
     * SPECIAL FLAGS
     * -------------------------------------------------------------------------
     *
     * Special flags are negative integers.
     *
     * They are:
     * - mutually exclusive
     * - never matched using bitwise operators
     *
     * When checking for a special flag, always compare using equality:
     *
     * ```rust,no_run
     * # use verter_core::utils::vue::patch_flags::PatchFlags;
     * # let patch_flag = PatchFlags::Cached.into_flag();
     * if patch_flag.is(PatchFlags::Cached) { /* ... */ }
     * ```
     */

    /**
     * Indicates a cached static vnode.
     *
     * This is also a hydration hint to skip the entire subtree,
     * since static content never needs to be updated.
     */
    Cached = -1,

    /**
     * Indicates that the diffing algorithm should bail out of optimized mode.
     *
     * Examples:
     * - block fragments created by `renderSlot()` with non-compiler-generated slots
     * - manually written render functions
     * - manually cloned vnodes
     *
     * These cases must always be fully diffed.
     */
    Bail = -2,
}

impl PatchFlags {
    /**
     * Convert a single patch flag into a runtime PatchFlag bitmask.
     *
     * This is the canonical way to start building a patch flag.
     */
    #[inline(always)]
    pub const fn into_flag(self) -> PatchFlag {
        PatchFlag(self as i16)
    }

    /**
     * Dev-only helper: returns the canonical flag name.
     *
     * Equivalent to `PatchFlagNames` in the original TypeScript.
     */
    #[inline(always)]
    pub const fn name(self) -> &'static str {
        match self {
            PatchFlags::Text => "TEXT",
            PatchFlags::Class => "CLASS",
            PatchFlags::Style => "STYLE",
            PatchFlags::Props => "PROPS",
            PatchFlags::FullProps => "FULL_PROPS",
            PatchFlags::NeedHydration => "NEED_HYDRATION",
            PatchFlags::StableFragment => "STABLE_FRAGMENT",
            PatchFlags::KeyedFragment => "KEYED_FRAGMENT",
            PatchFlags::UnkeyedFragment => "UNKEYED_FRAGMENT",
            PatchFlags::NeedPatch => "NEED_PATCH",
            PatchFlags::DynamicSlots => "DYNAMIC_SLOTS",
            PatchFlags::DevRootFragment => "DEV_ROOT_FRAGMENT",
            PatchFlags::Cached => "CACHED",
            PatchFlags::Bail => "BAIL",
        }
    }

    /**
     * Returns true if this is a special (negative) flag.
     */
    #[inline(always)]
    pub const fn is_special(self) -> bool {
        (self as i16) < 0
    }
}

/**
 * Runtime wrapper for patch flags.
 *
 * Matches Vue’s internal representation:
 * - `> 0`  → optimized bitmask
 * - `< 0`  → special flag
 */
#[derive(Debug, Copy, Clone, Eq, PartialEq)]
pub struct PatchFlag(pub i16);

impl PatchFlag {
    #[inline(always)]
    pub const fn new(value: i16) -> Self {
        Self(value)
    }

    /**
     * Returns an empty patch flag.
     */
    #[inline(always)]
    pub const fn empty() -> Self {
        Self(0)
    }

    /// Returns true if this is a special (negative) flag.
    #[inline(always)]
    pub const fn is_special(self) -> bool {
        self.0 < 0
    }

    /// Returns true if this is a bitmask optimized patch flag.
    #[inline(always)]
    pub const fn is_optimized(self) -> bool {
        self.0 > 0
    }

    /**
     * Bitwise membership check.
     *
     * Only valid when `patchFlag > 0`.
     */
    #[inline(always)]
    pub const fn contains(self, flag: PatchFlags) -> bool {
        (self.0 & (flag as i16)) != 0
    }

    /**
     * Alias for contains().
     */
    #[inline(always)]
    pub const fn has(self, flag: PatchFlags) -> bool {
        self.contains(flag)
    }

    /**
     * Equality check for special flags.
     *
     * This is the correct way to check for:
     * - CACHED
     * - BAIL
     */
    #[inline(always)]
    pub const fn is(self, flag: PatchFlags) -> bool {
        self.0 == flag as i16
    }

    /**
     * Add a patch flag to this patch flag bitmask.
     *
     * Equivalent to bitwise OR (`|`) in TypeScript:
     *
     * ```js
     * const flag = TEXT | CLASS
     * ```
     *
     * WARNING:
     * Special negative flags (CACHED, BAIL) are mutually exclusive and cannot
     * be combined with bitmask flags.
     */
    #[inline(always)]
    pub const fn add(self, flag: PatchFlags) -> Self {
        let f = flag as i16;

        // If either side is special, result must be special and exclusive.
        // We treat this as an overwrite, matching Vue's semantic expectation:
        // special flags are standalone.
        if self.0 < 0 || f < 0 {
            return Self(f);
        }

        Self(self.0 | f)
    }

    /**
     * Alias for add(), useful for fluent chaining.
     */
    #[inline(always)]
    pub const fn with(self, flag: PatchFlags) -> Self {
        self.add(flag)
    }

    /**
     * Remove a patch flag from this patch flag bitmask.
     *
     * Equivalent to `flag & ~MASK`.
     *
     * If this is a special flag, removal is a no-op.
     */
    #[inline(always)]
    pub const fn remove(self, flag: PatchFlags) -> Self {
        if self.0 < 0 {
            return self;
        }

        let f = flag as i16;
        if f < 0 {
            return self;
        }

        Self(self.0 & !f)
    }

    /**
     * Alias for remove().
     */
    #[inline(always)]
    pub const fn without(self, flag: PatchFlags) -> Self {
        self.remove(flag)
    }

    /**
     * Combine two PatchFlag values (bitwise OR).
     *
     * If either flag is special (negative), the special one wins.
     */
    #[inline(always)]
    pub const fn union(self, other: PatchFlag) -> Self {
        if self.0 < 0 {
            return self;
        }
        if other.0 < 0 {
            return other;
        }
        Self(self.0 | other.0)
    }

    /**
     * Clears all flags (sets to 0).
     *
     * This will also clear special flags.
     */
    #[inline(always)]
    pub const fn clear(self) -> Self {
        let _ = self;
        Self(0)
    }

    /**
     * Add a patch flag to this patch flag bitmask WITHOUT checking for special flags.
     *
     * This is the absolute fastest version (single OR), intended for hot paths
     * where you already know:
     *
     * - `self.0 > 0` (optimized bitmask mode), and
     * - `flag` is NOT a special negative flag (CACHED / BAIL).
     *
     * Using this incorrectly can produce nonsense results (mixing negative flags
     * into a bitmask), so it is marked `unsafe` to force callers to acknowledge
     * the invariant.
     *
     * Equivalent to:
     * ```rust,ignore
     * PatchFlag(self.0 | (flag as i16))
     * ```
     */
    #[inline(always)]
    pub const unsafe fn add_unchecked(self, flag: PatchFlags) -> Self {
        Self(self.0 | (flag as i16))
    }

    /**
     * Remove a patch flag from this patch flag bitmask WITHOUT checking for special flags.
     *
     * Fastest version (AND + NOT), intended for hot paths with the same invariants
     * as `add_unchecked`.
     */
    #[inline(always)]
    pub const unsafe fn remove_unchecked(self, flag: PatchFlags) -> Self {
        Self(self.0 & !(flag as i16))
    }

    /**
     * Remove a combined PatchFlag bitmask WITHOUT checking for special flags.
     *
     * Like `remove_unchecked` but accepts a pre-combined `PatchFlag` mask,
     * allowing multiple flags to be cleared in a single operation.
     */
    #[inline(always)]
    pub const unsafe fn remove_mask_unchecked(self, mask: PatchFlag) -> Self {
        Self(self.0 & !mask.0)
    }

    /**
     * Bitwise membership check WITHOUT checking mode.
     *
     * Fastest version (AND + compare), intended for hot paths where `self.0 > 0`
     * and `flag` is positive.
     */
    #[inline(always)]
    pub const unsafe fn contains_unchecked(self, flag: PatchFlags) -> bool {
        (self.0 & (flag as i16)) != 0
    }

    /**
     * Dev-only helper: returns the canonical flag name.
     *
     * Equivalent to `PatchFlagNames` in the original TypeScript.
     *
     * NOTE:
     * If this is a combined bitmask, it returns "COMBINED".
     */
    #[inline(always)]
    pub const fn name(self) -> &'static str {
        match self.0 {
            x if x == PatchFlags::Text as i16 => "TEXT",
            x if x == PatchFlags::Class as i16 => "CLASS",
            x if x == PatchFlags::Style as i16 => "STYLE",
            x if x == PatchFlags::Props as i16 => "PROPS",
            x if x == PatchFlags::FullProps as i16 => "FULL_PROPS",
            x if x == PatchFlags::NeedHydration as i16 => "NEED_HYDRATION",
            x if x == PatchFlags::StableFragment as i16 => "STABLE_FRAGMENT",
            x if x == PatchFlags::KeyedFragment as i16 => "KEYED_FRAGMENT",
            x if x == PatchFlags::UnkeyedFragment as i16 => "UNKEYED_FRAGMENT",
            x if x == PatchFlags::NeedPatch as i16 => "NEED_PATCH",
            x if x == PatchFlags::DynamicSlots as i16 => "DYNAMIC_SLOTS",
            x if x == PatchFlags::DevRootFragment as i16 => "DEV_ROOT_FRAGMENT",
            x if x == PatchFlags::Cached as i16 => "CACHED",
            x if x == PatchFlags::Bail as i16 => "BAIL",
            0 => "NONE",
            _ => "COMBINED",
        }
    }
}

/**
 * Optional ergonomic constants.
 *
 * This allows:
 *
 * ```rust
 * # use verter_core::utils::vue::patch_flags::{PatchFlags, TEXT};
 * let flag = TEXT.add(PatchFlags::Class);
 * ```
 *
 * or:
 *
 * ```rust
 * # use verter_core::utils::vue::patch_flags::{TEXT, CLASS};
 * let flag = TEXT.union(CLASS);
 * ```
 */
pub const TEXT: PatchFlag = PatchFlag(PatchFlags::Text as i16);
pub const CLASS: PatchFlag = PatchFlag(PatchFlags::Class as i16);
pub const STYLE: PatchFlag = PatchFlag(PatchFlags::Style as i16);
pub const PROPS: PatchFlag = PatchFlag(PatchFlags::Props as i16);
pub const FULL_PROPS: PatchFlag = PatchFlag(PatchFlags::FullProps as i16);
pub const NEED_HYDRATION: PatchFlag = PatchFlag(PatchFlags::NeedHydration as i16);
pub const STABLE_FRAGMENT: PatchFlag = PatchFlag(PatchFlags::StableFragment as i16);
pub const KEYED_FRAGMENT: PatchFlag = PatchFlag(PatchFlags::KeyedFragment as i16);
pub const UNKEYED_FRAGMENT: PatchFlag = PatchFlag(PatchFlags::UnkeyedFragment as i16);
pub const NEED_PATCH: PatchFlag = PatchFlag(PatchFlags::NeedPatch as i16);
pub const DYNAMIC_SLOTS: PatchFlag = PatchFlag(PatchFlags::DynamicSlots as i16);
pub const DEV_ROOT_FRAGMENT: PatchFlag = PatchFlag(PatchFlags::DevRootFragment as i16);
pub const CACHED: PatchFlag = PatchFlag(PatchFlags::Cached as i16);
pub const BAIL: PatchFlag = PatchFlag(PatchFlags::Bail as i16);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn build_flags_fluent() {
        let flag = PatchFlags::Text
            .into_flag()
            .add(PatchFlags::Class)
            .add(PatchFlags::Style);

        assert!(flag.contains(PatchFlags::Text));
        assert!(flag.contains(PatchFlags::Class));
        assert!(flag.contains(PatchFlags::Style));
        assert!(!flag.contains(PatchFlags::Props));
    }

    #[test]
    fn remove_flags() {
        let flag = PatchFlags::Text
            .into_flag()
            .add(PatchFlags::Class)
            .add(PatchFlags::Style)
            .remove(PatchFlags::Class);

        assert!(flag.contains(PatchFlags::Text));
        assert!(!flag.contains(PatchFlags::Class));
        assert!(flag.contains(PatchFlags::Style));
    }

    #[test]
    fn constants_work() {
        let flag = TEXT.union(CLASS).union(STYLE);

        assert!(flag.contains(PatchFlags::Text));
        assert!(flag.contains(PatchFlags::Class));
        assert!(flag.contains(PatchFlags::Style));
    }

    #[test]
    fn special_flags_override() {
        let flag = TEXT.union(CLASS).add(PatchFlags::Cached); // overwrites to special

        assert!(flag.is(PatchFlags::Cached));
        assert!(flag.is_special());
        assert_eq!(flag.name(), "CACHED");
    }

    #[test]
    fn clearing_works() {
        let flag = TEXT.union(CLASS).clear();
        assert_eq!(flag.0, 0);
        assert_eq!(flag.name(), "NONE");
    }

    #[test]
    fn unchecked_add_remove_contains() {
        let flag = PatchFlags::Text.into_flag();

        // SAFETY: we only use positive flags here, and we treat it as bitmask mode.
        let flag = unsafe { flag.add_unchecked(PatchFlags::Class) };
        assert!(unsafe { flag.contains_unchecked(PatchFlags::Text) });
        assert!(unsafe { flag.contains_unchecked(PatchFlags::Class) });

        let flag = unsafe { flag.remove_unchecked(PatchFlags::Text) };
        assert!(!unsafe { flag.contains_unchecked(PatchFlags::Text) });
        assert!(unsafe { flag.contains_unchecked(PatchFlags::Class) });
    }
}
